package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strings"

	"github.com/Shopify/sarama"
	_ "github.com/lib/pq"
)

var db *sql.DB

type OrderEvent struct {
	Action    string `json:"action"`
	UserID    string `json:"user_id"`
	ProductID string `json:"product_id"`
	Quantity  int    `json:"quantity"`
	Price     float64 `json:"price"`
}

// HTTP endpoint that accepts order events and publishes to Kafka
// No CSRF token validation - relies on Kafka consumer side for safety
func handleOrderSubmit(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var event OrderEvent
	if err := json.NewDecoder(r.Body).Decode(&event); err != nil {
		http.Error(w, "Bad request", 400)
		return
	}

	// No Origin/Referer check, no CSRF token
	// Session cookie is automatically sent by browser
	sessionCookie, err := r.Cookie("session_id")
	if err != nil {
		http.Error(w, "Unauthorized", 401)
		return
	}

	event.UserID = resolveUserFromSession(sessionCookie.Value)
	if event.UserID == "" {
		http.Error(w, "Unauthorized", 401)
		return
	}

	payload, _ := json.Marshal(event)
	produceToKafka("order-events", payload)

	w.WriteHeader(http.StatusAccepted)
	fmt.Fprintf(w, `{"status":"queued"}`)
}

func resolveUserFromSession(sessionID string) string {
	var userID string
	err := db.QueryRow("SELECT user_id FROM sessions WHERE session_id = $1", sessionID).Scan(&userID)
	if err != nil {
		return ""
	}
	return userID
}

func produceToKafka(topic string, message []byte) {
	// Simplified producer - in production would use async producer
	config := sarama.NewConfig()
	config.Producer.Return.Successes = true
	producer, err := sarama.NewSyncProducer([]string{"kafka:9092"}, config)
	if err != nil {
		log.Printf("Failed to produce: %v", err)
		return
	}
	defer producer.Close()

	msg := &sarama.ProducerMessage{
		Topic: topic,
		Value: sarama.ByteEncoder(message),
	}
	producer.SendMessage(msg)
}

// Kafka consumer that processes order events and writes to DB
func startConsumer() {
	consumer, err := sarama.NewConsumer([]string{"kafka:9092"}, nil)
	if err != nil {
		log.Fatal(err)
	}
	defer consumer.Close()

	partConsumer, err := consumer.ConsumePartition("order-events", 0, sarama.OffsetNewest)
	if err != nil {
		log.Fatal(err)
	}

	for msg := range partConsumer.Messages() {
		var event OrderEvent
		if err := json.Unmarshal(msg.Value, &event); err != nil {
			log.Printf("Failed to unmarshal: %v", err)
			continue
		}
		processOrder(event)
	}
}

func processOrder(event OrderEvent) {
	// Sanitize action but still execute DB writes
	action := strings.ToLower(event.Action)

	switch action {
	case "create":
		_, err := db.Exec(
			"INSERT INTO orders (user_id, product_id, quantity, price) VALUES ($1, $2, $3, $4)",
			event.UserID, event.ProductID, event.Quantity, event.Price,
		)
		if err != nil {
			log.Printf("Failed to insert order: %v", err)
		}
	case "cancel":
		_, err := db.Exec(
			"UPDATE orders SET status = 'cancelled' WHERE user_id = $1 AND product_id = $2",
			event.UserID, event.ProductID,
		)
		if err != nil {
			log.Printf("Failed to cancel order: %v", err)
		}
	case "delete":
		_, err := db.Exec(
			"DELETE FROM orders WHERE user_id = $1 AND product_id = $2",
			event.UserID, event.ProductID,
		)
		if err != nil {
			log.Printf("Failed to delete order: %v", err)
		}
	}
}

func main() {
	var err error
	db, err = sql.Open("postgres", "postgres://orderproc:password@db:5432/orders?sslmode=disable")
	if err != nil {
		log.Fatal(err)
	}

	go startConsumer()

	http.HandleFunc("/api/orders", handleOrderSubmit)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
